/bin/bash -lc "python - <<'PY'
from pathlib import Path
files = [
    '/home/lixinyu/snap/new/ARC_code/train/6165ea8f.py',
    '/home/lixinyu/snap/new/ARC_code/train/2601afb7.py',
    '/home/lixinyu/snap/new/ARC_code/eval/a32d8b75.py',
    '/home/lixinyu/snap/new/ARC_code/train/2ccd9fef.py',
]
for path in files:
    text = Path(path).read_text().splitlines()
    print(f'===== {Path(path).name} =====')
    for fn in ('main', 'generate_input'):
        start = next(i for i,l in enumerate(text) if l.startswith(f'def {fn}('))
        end = len(text)
        for j in range(start+1, len(text)):
            if text[j].startswith('def ') and not text[j].startswith(f'def {fn}('):
                end = j
                break
        snippet = text[start:min(end, start+110)]
        print(f'--- {fn} ---')
        for k, line in enumerate(snippet, start+1):
            print(f'{k:4d}: {line}')
PY"

